package dev.zomboidmelee.boxing;
/** A committed impact pulse on the final camera, including cameras that overwrite the viewport event. */
public final class Shake32{
 static double[] pulse(int kind,double phase,double seconds,int combo){if(phase<0||phase>=1||kind==Motion20.INTERACT||kind==Motion20.SEARCH)return new double[]{0,0};double strength=kind==Motion20.STOMP?5.4:kind==Motion20.HEAVY?3.9:kind==Motion20.SHOVE?2.4:2.0;double wind=kind==Motion20.STOMP?0:Motion20.strike(kind,phase),hit=seconds<0||seconds>.32?0:Math.sin(seconds*35)*Math.exp(-seconds*13);return new double[]{Math.max(-6,Math.min(6,wind*.35*strength+hit*strength)),(combo%2==0?1:-1)*(wind*.18*strength+hit*strength*.45)};}
 static double actual(Object camera,String field,String getter){try{return R.num(R.get(camera,field));}catch(IllegalStateException absent){return R.num(R.call(camera,getter));}}
 public static void camera(Object camera){Object mc=BoxingClient16.mc(),p=R.get(mc,"player");if(p==null||R.get(mc,"screen")!=null||!R.yes(R.call(p,"isAlive"))||R.call(camera,"getEntity")!=p)return;Client20.State s=Client20.state(p);if(!Boxing16.empty(p)&&s.kind!=Motion20.SHOVE)return;double phase=Client20.phase(p);long impact=s.contact==0?s.start+(long)(Motion20.impact(s.kind)*Motion20.duration(s.kind)):s.contact;double[]kick=pulse(s.kind,phase,(Client20.now()-impact)/1e9,s.combo);if(Math.abs(kick[0])+Math.abs(kick[1])<.001)return;double roll=0;try{roll=R.num(R.get(camera,"roll"));}catch(IllegalStateException absent){}R.call(camera,"setRotation",(float)actual(camera,"yRot","getYRot"),(float)(actual(camera,"xRot","getXRot")+kick[0]),(float)(roll+kick[1]));}
}
